import type { RegionId } from '@/engine/types';

import geometry from './geometry.json';

/** One region's shape in map units (generated by scripts/map/build-geometry.js). */
export interface RegionGeometry {
  /** SVG path data. */
  d: string;
  /** Marker point [x, y] on the region's main landmass. */
  centroid: [number, number];
  /** [minX, minY, maxX, maxY]. */
  bbox: [number, number, number, number];
  /** Projected area in square map units. */
  area: number;
}

export interface MapGeometry {
  version: number;
  width: number;
  height: number;
  viewBox: [number, number, number, number];
  regions: Record<RegionId, RegionGeometry>;
}

/** Generated map geometry of the ai-lab pack. Do not edit geometry.json by hand: run `npm run build:map`. */
export const aiLabGeometry = geometry as unknown as MapGeometry;
